-- ─── SUBCHUNK COMPLETION VERIFICATION ─────────────────────────────────────────
DO $$
DECLARE
  v_inserted_sample BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM public.candidacies
    WHERE id = '0215b22d-0002-0000-0000-000000001151'::uuid
  ) INTO v_inserted_sample;

  IF NOT v_inserted_sample THEN
    RAISE EXCEPTION 'FAIL-CLOSED: Candidacy Chunk 06B sample record % missing', '0215b22d-0002-0000-0000-000000001151';
  END IF;
END $$;

COMMIT;
